<?php
/**
 * Plugin Name: {{TITLE}} internal license — verification mock
 * Description: TEMPORARY. For a development site only. Remove it when the check is done.
 *
 * Generated by the wc-am-internal-license skill (generate.py --verify-mock).
 *
 * - Defines {{KEY_CONSTANT}} with a dummy key, unless the option wcam_mock_no_key is set.
 * - Answers every request to {{API_HOST}} instead of the real store, so nothing leaves the site.
 *   The option wcam_mock_mode picks the answer to activation: success | already | fail.
 * - Logs each request (without the key itself) to the option wcam_mock_log.
 *
 * The file name starts with "0-" so it loads before the generated mu-plugin, which reads the constant
 * when it loads.
 *
 * @package {{PACKAGE}}
 */

defined( 'ABSPATH' ) || exit;

const WCAM_MOCK_KEY = 'verify0123456789abcdef0123456789abcdef00';

if ( ! get_option( 'wcam_mock_no_key' ) && ! defined( '{{KEY_CONSTANT}}' ) ) {
	define( '{{KEY_CONSTANT}}', WCAM_MOCK_KEY );
}

add_filter(
	'pre_http_request',
	static function ( $preempt, $args, $url ) {
		if ( '{{API_HOST}}' !== wp_parse_url( $url, PHP_URL_HOST ) ) {
			return $preempt;
		}

		parse_str( (string) wp_parse_url( $url, PHP_URL_QUERY ), $query );
		$body   = is_array( $args['body'] ?? null ) ? $args['body'] : array();
		$params = array_merge( $query, $body );
		$action = $params['wc_am_action'] ?? '';
		$mode   = get_option( 'wcam_mock_mode', 'success' );
		$key_ok = WCAM_MOCK_KEY === ( $params['api_key'] ?? '' );

		$log   = get_option( 'wcam_mock_log', array() );
		$log[] = array(
			'action'      => $action,
			'key_in_url'  => isset( $query['api_key'] ) && '' !== $query['api_key'],
			'key_in_body' => isset( $body['api_key'] ) && '' !== $body['api_key'],
			'key_ok'      => $key_ok,
			'product_id'  => $params['product_id'] ?? null,
			'instance'    => $params['instance'] ?? null,
			'object'      => $params['object'] ?? null,
			'version'     => $params['software_version'] ?? null,
			'redirection' => $args['redirection'] ?? null,
		);
		update_option( 'wcam_mock_log', $log, false );

		$activated = (bool) get_option( 'wcam_mock_activated' );
		$json      = null;

		if ( 'activate' === $action ) {
			if ( 'fail' === $mode || ! $key_ok ) {
				$json = array(
					'success' => false,
					'data'    => array(
						'error_code' => '100',
						'error'      => 'A customer account does not exist for this <b>license key</b>.',
					),
				);
			} elseif ( 'already' === $mode ) {
				update_option( 'wcam_mock_activated', 1, false );
				$json = array(
					'success' => false,
					'data'    => array(
						'error_code' => '100',
						'error'      => 'Cannot activate license key. The license key has already been activated with the same unique instance ID sent with this request.',
					),
				);
			} else {
				update_option( 'wcam_mock_activated', 1, false );
				$json = array(
					'activated' => true,
					'success'   => true,
					'message'   => '99999 out of 100000 activations remaining',
				);
			}
		} elseif ( 'status' === $action ) {
			$json = ( 'fail' === $mode || ! $key_ok )
				? array(
					'success' => false,
					'data'    => array(
						'error_code' => '100',
						'error'      => 'A customer account does not exist for this license key.',
					),
				)
				: array(
					'success'      => true,
					'status_check' => $activated ? 'active' : 'inactive',
					'data'         => array( 'activated' => $activated ),
				);
		} elseif ( 'update' === $action ) {
			$json = array(
				'success' => true,
				'data'    => array(
					'package' => array(
						'id'             => '{{SLUG}}-{{PRODUCT_ID}}',
						'slug'           => '{{SLUG}}',
						'plugin'         => '{{PLUGIN_FILE}}',
						'new_version'    => '9.9.9',
						'url'            => 'https://{{API_HOST}}/',
						'tested'         => '7.1',
						'upgrade_notice' => '',
						'package'        => ( $activated && $key_ok ) ? 'https://{{API_HOST}}/?am_download_file={{PRODUCT_ID}}&verify=1' : '',
					),
				),
			);
		}

		return array(
			'headers'  => array(),
			'body'     => null === $json ? '' : wp_json_encode( $json ),
			'response' => array(
				'code'    => 200,
				'message' => 'OK',
			),
			'cookies'  => array(),
			'filename' => null,
		);
	},
	10,
	3
);
